import Form from 'flarum/common/components/Form';
import FormModal from 'flarum/common/components/FormModal';
import app from 'flarum/admin/app';
import Button from 'flarum/common/components/Button';
import { slug } from 'flarum/common/utils/string';
export default class TeamModal extends FormModal {
  name = '';
  slug = '';
  logoPath = '';
  loading = false;
  // YENİ: Yükleme durumu için state
  uploadLoading = false;
  oninit(vnode) {
    super.oninit(vnode);
    this.team = this.attrs.team;
    if (this.team) {
      this.name = this.team.name() || '';
      this.slug = this.team.slug() || '';
      this.logoPath = this.team.logoPath() || '';
    }
  }
  className() {
    return 'TeamModal Modal--small';
  }
  title() {
    return this.team ? app.translator.trans('huseyinfiliz-pickem.lib.actions.edit') : app.translator.trans('huseyinfiliz-pickem.lib.actions.create');
  }
  content() {
    // FoF Upload uzantısının aktif olup olmadığını kontrol et
    const hasFofUpload = 'fof-upload' in (app.data.extensions ?? {});
    return m("div", {
      className: "Modal-body"
    }, m(Form, null, m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('huseyinfiliz-pickem.lib.form.name')), m("input", {
      className: "FormControl",
      type: "text",
      value: this.name,
      oninput: e => {
        this.name = e.target.value;
        if (!this.team) {
          this.slug = slug(this.name);
        }
      }
    })), m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('huseyinfiliz-pickem.lib.form.slug')), m("input", {
      className: "FormControl",
      type: "text",
      value: this.slug,
      oninput: e => {
        this.slug = e.target.value;
      }
    })), m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('huseyinfiliz-pickem.lib.form.logo_url')), m("div", {
      style: {
        display: 'flex',
        gap: '8px'
      }
    }, m("input", {
      className: "FormControl",
      type: "text",
      value: this.logoPath,
      oninput: e => {
        this.logoPath = e.target.value;
      },
      placeholder: "https://example.com/logo.png",
      style: {
        flex: 1
      }
    }), hasFofUpload && m('[', null, m("input", {
      id: "pickem-logo-upload",
      type: "file",
      accept: "image/*",
      style: {
        display: 'none'
      },
      onchange: this.handleUpload.bind(this)
    }), m(Button, {
      className: "Button Button--icon",
      icon: "fas fa-cloud-upload-alt",
      loading: this.uploadLoading,
      onclick: () => {
        const fileInput = document.getElementById('pickem-logo-upload');
        if (fileInput) fileInput.click();
      },
      title: "Upload with FoF Upload",
      type: "button"
    }))), this.logoPath && m("div", {
      style: {
        marginTop: '10px'
      }
    }, m("img", {
      src: this.logoPath,
      alt: "Logo preview",
      style: {
        maxWidth: '100px',
        maxHeight: '100px',
        border: '1px solid #ddd',
        padding: '5px',
        borderRadius: '4px'
      },
      onerror: e => {
        e.target.style.display = 'none';
      }
    }))), m("div", {
      className: "Form-group"
    }, m(Button, {
      className: "Button Button--primary",
      type: "submit",
      loading: this.loading
    }, app.translator.trans('huseyinfiliz-pickem.lib.buttons.save')))));
  }

  // YENİ: Dosya yükleme işleyicisi
  async handleUpload(e) {
    const target = e.target;
    if (!target.files || target.files.length === 0) return;
    const file = target.files[0];
    const formData = new FormData();
    formData.append('files[]', file);
    this.uploadLoading = true;
    m.redraw();
    try {
      // FoF Upload API'sine istek at
      const response = await app.request({
        method: 'POST',
        url: app.forum.attribute('apiUrl') + '/fof/upload',
        body: formData,
        serialize: raw => raw // FormData'yı JSON'a çevirme, olduğu gibi gönder
      });

      // Gelen yanıttan URL'i al (FoF Upload JSON:API standardı kullanır)
      if (response && response.data && response.data[0] && response.data[0].attributes) {
        this.logoPath = response.data[0].attributes.url;
        app.alerts.show({
          type: 'success'
        }, app.translator.trans('huseyinfiliz-pickem.lib.messages.saved')); // Opsiyonel başarı mesajı
      }
    } catch (error) {
      console.error('Logo upload failed:', error);
      app.alerts.show({
        type: 'error'
      }, 'Upload failed. Check console for details.');
    } finally {
      this.uploadLoading = false;
      target.value = ''; // Inputu temizle ki aynı dosya tekrar seçilebilsin
      m.redraw();
    }
  }
  async onsubmit(e) {
    e.preventDefault();
    this.loading = true;
    m.redraw();
    const data = {
      name: this.name,
      slug: this.slug,
      logoPath: this.logoPath
    };
    try {
      const promise = this.team ? this.team.save(data) : app.store.createRecord('pickem-teams').save(data);
      await promise;
      this.attrs.onsave();
      this.hide();
    } catch (error) {
      this.loading = false;
      this.alertAttrs = error.alert;
      m.redraw();
    }
  }
}
flarum.reg.add('huseyinfiliz-pickem', 'admin/components/modals/TeamModal', TeamModal);